// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.iterator;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;

import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.QueryEvaluationContext;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.junit.jupiter.api.Test;

/**
 * Compares hash joins with partially bound keys against a nested-loop reference join.
 */
public class HashJoinIterationFuzzTest {

	private static final String[] SHARED = { "a", "b", "c" };

	private static final String[][] KEY_SETS = {
			{ "a", "b", "c" }, // exact
			{ "b" }, // too small
			{ "a", "b", "c", "never" }, // too large
			{}, // none
	};

	@Test
	public void hashJoinMatchesNestedLoopReference() {
		hashJoinMatchesNestedLoopReference(new Random(20260925L));
	}

	@Test
	public void hashJoinMatchesNestedLoopReferenceWhenSecondaryIndexesAreBuilt() {
		int minGroupSize = PartialKeyHashLookup.minIndexedGroupSize;
		int budget = PartialKeyHashLookup.maxIndexEntriesPerBuildKey;
		PartialKeyHashLookup.minIndexedGroupSize = 1;
		PartialKeyHashLookup.maxIndexEntriesPerBuildKey = 1;
		try {
			// a budget of one entry per build key forces some groups to be indexed and later ones to be scanned
			hashJoinMatchesNestedLoopReference(new Random(20260927L));
		} finally {
			PartialKeyHashLookup.minIndexedGroupSize = minGroupSize;
			PartialKeyHashLookup.maxIndexEntriesPerBuildKey = budget;
		}
	}

	private void hashJoinMatchesNestedLoopReference(Random random) {
		for (int round = 0; round < 400; round++) {
			List<BindingSet> left = randomRows(random, "l");
			List<BindingSet> right = randomRows(random, "r");
			for (String[] keys : KEY_SETS) {
				for (boolean leftJoin : new boolean[] { false, true }) {
					HashJoinIteration iteration = new HashJoinIteration(JoinTestSupport.step(left),
							JoinTestSupport.step(right), EmptyBindingSet.getInstance(), leftJoin, keys,
							new QueryEvaluationContext.Minimal(null));
					assertEquals(JoinTestSupport.referenceJoin(left, right, leftJoin), JoinTestSupport.drain(iteration),
							"round " + round + " keys " + String.join(",", keys) + " leftJoin=" + leftJoin);
				}
			}
		}
	}

	@Test
	public void scopedLeftJoinMatchesNestedLoopReference() {
		Random random = new Random(20260926L);
		for (int round = 0; round < 400; round++) {
			List<BindingSet> left = randomRows(random, "l");
			List<BindingSet> right = randomRows(random, "r");
			for (String[] keys : KEY_SETS) {
				ScopedLeftJoinIterator iteration = new ScopedLeftJoinIterator(JoinTestSupport.step(left),
						JoinTestSupport.step(right), null, EmptyBindingSet.getInstance(),
						new QueryEvaluationContext.Minimal(null), keys);
				assertEquals(JoinTestSupport.referenceJoin(left, right, true), JoinTestSupport.drain(iteration),
						"round " + round + " keys " + String.join(",", keys));
			}
		}
	}

	private static List<BindingSet> randomRows(Random random, String payloadName) {
		int size = random.nextInt(25);
		List<BindingSet> rows = new ArrayList<>(size);
		for (int i = 0; i < size; i++) {
			String[] pairs = new String[2 * SHARED.length + 2];
			for (int j = 0; j < SHARED.length; j++) {
				pairs[2 * j] = SHARED[j];
				pairs[2 * j + 1] = random.nextInt(10) < 4 ? null : "v" + random.nextInt(3);
			}
			pairs[2 * SHARED.length] = payloadName;
			pairs[2 * SHARED.length + 1] = Integer.toString(i);
			rows.add(JoinTestSupport.row(pairs));
		}
		return rows;
	}
}
